/* @lc app=leetcode id=2747 lang=kotlin */
class Solution { fun countServers(n: Int, logs: Array<IntArray>, x: Int, queries: IntArray): IntArray = logs.sortedBy { it[1] }.let { l -> queries.indices.sortedBy { queries[it] }.let { sQIdx -> IntArray(n + 5).let { counts -> IntArray(3).let { v -> IntArray(queries.size).apply { sQIdx.forEach { i -> run { while (v[1] < l.size && l[v[1]][1] <= queries[i]) { (if (++counts[l[v[1]][0]] == 1) v[0]++ else 0).also { v[1]++ } } }.run { while (v[2] < l.size && l[v[2]][1] < queries[i] - x) { (if (--counts[l[v[2]][0]] == 0) v[0]-- else 0).also { v[2]++ } } }.run { this@apply[i] = n - v[0] } } } } } } } }